import sys

def main():
    input_data = sys.stdin.read().split()
    idx = 0
    if idx >= len(input_data):
        return
    N = int(input_data[idx])
    idx += 1
    M = int(input_data[idx])
    idx += 1

    A = []
    for _ in range(N):
        A.append(int(input_data[idx]))
        idx += 1

    B = []
    for _ in range(M):
        B.append(int(input_data[idx]))
        idx += 1

    b_set = set(B)
    filtered_A = [x for x in A if x in b_set]

    b_map = {val: i for i, val in enumerate(B)}

    if not filtered_A:
        print(M)
        return

    lis = []
    for x in filtered_A:
        pos = b_map[x]
        if not lis or pos > lis[-1]:
            lis.append(pos)
        else:
            low, high = 0, len(lis) - 1
            while low < high:
                mid = (low + high) // 2
                if lis[mid] >= pos:
                    high = mid
                else:
                    low = mid + 1
            lis[low] = pos

    lcs_len = len(lis)
    ans = (N - lcs_len) + (M - lcs_len)
    print(ans)

if __name__ == "__main__":
    main()
